// Layout: 4 maps per row. East portal (top-right) -> next level, west portal
// (bottom-left) -> previous level, south portal (bottom) -> level + 4, north
// portal (top) -> level - 4. You leave through the same door you came in.
// Bots per map: 3 neighbouring bot levels (see BOT_TYPES[...].level in
// bot_server.js): map N has level N-1, N, N+1 bots (LEVEL1 has 1,2,3) —
// 55 normal bots + 1 elite (the elite is the map's own level) = 56 per map.
// =============================================================================
